// Żaba: pola 1..n z wysokościami h[i]; skok o 1 lub 2 pola kosztuje |h[i] - h[j]|.
// Minimalny koszt dojścia z pola 1 na pole n + odtworzenie trasy.
#include <bits/stdc++.h>
using namespace std;

int main() {
    int n;
    cin >> n;
    vector<long long> h(n);
    for (auto &x : h) cin >> x;

    const long long INF = LLONG_MAX / 4;   // /4: dodanie kosztu nie przepełni typu
    vector<long long> dp(n, INF);          // dp[i] = minimalny koszt dojścia na pole i
    vector<int> par(n, -1);                // par[i] = skąd przyszliśmy (do odtworzenia)
    dp[0] = 0;                             // przypadek bazowy

    for (int i = 1; i < n; i++)            // kolejność: rosnąco, bo dp[i] zależy od dp[i-1], dp[i-2]
        for (int k = 1; k <= 2; k++) {
            if (i - k < 0) continue;
            long long c = dp[i - k] + llabs(h[i] - h[i - k]);
            if (c < dp[i]) { dp[i] = c; par[i] = i - k; }
        }

    cout << dp[n - 1] << "\n";
    vector<int> path;                      // odtwarzanie: cofamy się po par[] od końca
    for (int v = n - 1; v != -1; v = par[v]) path.push_back(v);
    reverse(path.begin(), path.end());
    for (int v : path) cout << v + 1 << " ";
    cout << "\n";
}

// Ta sama żaba w wersji z memoizacją (top-down).
#include <bits/stdc++.h>
using namespace std;

int n;
vector<long long> h, memo;
vector<bool> done;

long long f(int i) {                 // f(i) = minimalny koszt dojścia na pole i
    if (i == 0) return 0;
    if (done[i]) return memo[i];      // już policzone — zwracamy z pamięci
    long long r = f(i - 1) + llabs(h[i] - h[i - 1]);
    if (i >= 2) r = min(r, f(i - 2) + llabs(h[i] - h[i - 2]));
    done[i] = true;
    return memo[i] = r;
}

int main() {
    cin >> n;
    h.resize(n); memo.assign(n, 0); done.assign(n, false);
    for (auto &x : h) cin >> x;
    cout << f(n - 1) << "\n";
}

