// Schody: kroki o 1..k stopni, wynik modulo 10^9+7. Suma przesuwna => O(n) niezależnie od k.
#include <bits/stdc++.h>
using namespace std;
const long long MOD = 1'000'000'007;

int main() {
    long long n, k;
    cin >> n >> k;
    vector<long long> ways(n + 1, 0);
    ways[0] = 1;
    long long window = 1;            // suma ways[i-k .. i-1]
    for (long long i = 1; i <= n; i++) {
        ways[i] = window;
        window = (window + ways[i]) % MOD;              // wchodzi ways[i]
        if (i - k >= 0)                                 // wychodzi ways[i-k]
            window = (window - ways[i - k] + MOD) % MOD;
    }
    cout << ways[n] << "\n";
}

// Fibonacci iteracyjnie, O(n) czasu, O(1) pamięci.
long long fib(int n) {             // F(0)=0, F(1)=1; mieści się w long long do n = 92
    long long a = 0, b = 1;
    for (int i = 0; i < n; i++) {
        long long c = a + b;
        a = b;
        b = c;
    }
    return a;
}

