// Plecak 0/1: wejście n W, potem n par (waga, wartość).
// Wyjście: maksymalna wartość oraz numery wybranych przedmiotów (odtworzenie z tablicy 2D).
#include <bits/stdc++.h>
using namespace std;

int main() {
    int n, W;
    cin >> n >> W;
    vector<int> w(n + 1), v(n + 1);
    for (int i = 1; i <= n; i++) cin >> w[i] >> v[i];

    // dp[i][c] = najlepsza wartość z przedmiotów 1..i przy pojemności c
    vector<vector<long long>> dp(n + 1, vector<long long>(W + 1, 0));
    for (int i = 1; i <= n; i++)
        for (int c = 0; c <= W; c++) {
            dp[i][c] = dp[i - 1][c];                                   // nie bierzemy i
            if (c >= w[i]) dp[i][c] = max(dp[i][c], dp[i - 1][c - w[i]] + v[i]);  // bierzemy i
        }
    cout << dp[n][W] << "\n";

    // odtwarzanie: jeśli dp[i][c] != dp[i-1][c], to przedmiot i został wzięty
    vector<int> chosen;
    for (int i = n, c = W; i >= 1; i--)
        if (dp[i][c] != dp[i - 1][c]) { chosen.push_back(i); c -= w[i]; }
    reverse(chosen.begin(), chosen.end());
    for (int x : chosen) cout << x << " ";
    cout << "\n";
}

