// Plecak nieograniczony: n W, potem n par (waga, wartość). Wypisuje max wartość i jeden optymalny zestaw.
#include <bits/stdc++.h>
using namespace std;

int main() {
    int n, W;
    cin >> n >> W;
    vector<int> w(n), v(n);
    for (int i = 0; i < n; i++) cin >> w[i] >> v[i];

    vector<long long> dp(W + 1, 0);   // dp[c] = najlepsza wartość przy wadze <= c
    vector<int> last(W + 1, -1);      // ostatni wzięty przedmiot w optimum dla c (-1 = żaden)
    for (int c = 1; c <= W; c++) {
        dp[c] = dp[c - 1]; last[c] = -2;          // -2: "zmarnuj" jednostkę pojemności
        for (int i = 0; i < n; i++)
            if (w[i] <= c && dp[c - w[i]] + v[i] > dp[c]) {
                dp[c] = dp[c - w[i]] + v[i];
                last[c] = i;
            }
    }
    cout << dp[W] << "\n";

    vector<int> cnt(n, 0);            // odtworzenie: ile sztuk każdego przedmiotu
    for (int c = W; c > 0; ) {
        if (last[c] == -2) { c--; continue; }
        cnt[last[c]]++;
        c -= w[last[c]];
    }
    for (int i = 0; i < n; i++) cout << cnt[i] << " ";
    cout << "\n";
}

