// Plecak ograniczony: n W, potem n trójek (waga, wartość, liczba sztuk).
#include <bits/stdc++.h>
using namespace std;

int main() {
    int n, W;
    cin >> n >> W;
    vector<pair<long long, long long>> packs;      // (waga, wartość) paczek 0/1
    for (int i = 0; i < n; i++) {
        long long w, v, c;
        cin >> w >> v >> c;
        for (long long s = 1; c > 0; s *= 2) {      // paczki 1, 2, 4, ... i reszta
            long long take = min(s, c);
            packs.push_back({take * w, take * v});
            c -= take;
        }
    }
    vector<long long> dp(W + 1, 0);
    for (auto [pw, pv] : packs)                     // zwykły plecak 0/1 na paczkach
        for (long long cap = W; cap >= pw; cap--)
            dp[cap] = max(dp[cap], dp[cap - pw] + pv);
    cout << dp[W] << "\n";
}

