    vector<char> can(S + 1, 0);
    can[0] = 1;
    vector<int> used(S + 1);
    for (int i = 0; i < n; i++) {
        int a, c;
        cin >> a >> c;
        fill(used.begin(), used.end(), 0);
        for (int s = a; s <= S; s++)
            if (!can[s] && can[s - a] && used[s - a] < c) {
                can[s] = 1;
                used[s] = used[s - a] + 1;
            }
