// Wejście: n S, potem n nominałów. Wyjście: minimalna liczba monet (lub -1) + użyte monety,
// liczba sposobów (zbiory) i liczba ciągów, obie modulo 10^9+7.
#include <bits/stdc++.h>
using namespace std;
const long long MOD = 1'000'000'007;

int main() {
    int n, S;
    cin >> n >> S;
    vector<int> c(n);
    for (auto &x : c) cin >> x;

    const int INF = 1e9;
    vector<int> best(S + 1, INF), from(S + 1, -1);
    best[0] = 0;
    for (int s = 1; s <= S; s++)
        for (int x : c)
            if (x <= s && best[s - x] != INF && best[s - x] + 1 < best[s]) {
                best[s] = best[s - x] + 1;
                from[s] = x;                     // ostatnia użyta moneta
            }
    if (best[S] == INF) cout << -1 << "\n";
    else {
        cout << best[S] << ":";
        for (int s = S; s > 0; s -= from[s]) cout << " " << from[s];
        cout << "\n";
    }

    vector<long long> ways(S + 1, 0);           // zbiory monet: monety na zewnątrz
    ways[0] = 1;
    for (int x : c)
        for (int s = x; s <= S; s++) ways[s] = (ways[s] + ways[s - x]) % MOD;

    vector<long long> seq(S + 1, 0);            // ciągi monet: suma na zewnątrz
    seq[0] = 1;
    for (int s = 1; s <= S; s++)
        for (int x : c)
            if (x <= s) seq[s] = (seq[s] + seq[s - x]) % MOD;

    cout << ways[S] << " " << seq[S] << "\n";
}

