// minimalna liczba monet dla dowolnie dużego S (-1 gdy się nie da); nominały dodatnie, różne
long long minCoinsLarge(vector<long long> coins, long long S) {
    long long c = *max_element(coins.begin(), coins.end());
    long long t = 0;
    if (S >= c * c) { t = (S - c * c) / c + 1; S -= t * c; }   // teraz S < c*c
    const long long INF = LLONG_MAX / 4;
    vector<long long> dp(S + 1, INF);
    dp[0] = 0;
    for (long long s = 1; s <= S; s++)
        for (long long x : coins) if (x <= s && dp[s - x] + 1 < dp[s]) dp[s] = dp[s - x] + 1;
    return dp[S] >= INF ? -1 : dp[S] + t;
}
int main() {
    mt19937 rng(1);
    for (int it = 0; it < 300; it++) {                     // porównanie z pełnym DP
        set<long long> st;
        int k = rng() % 3 + 1;
        while ((int)st.size() < k) st.insert(rng() % 12 + 1);
        vector<long long> coins(st.begin(), st.end());
        long long S = rng() % 2000;
        vector<long long> dp(S + 1, LLONG_MAX / 4); dp[0] = 0;
        for (long long s = 1; s <= S; s++) for (long long x : coins) if (x <= s) dp[s] = min(dp[s], dp[s - x] + 1);
        long long full = dp[S] >= LLONG_MAX / 4 ? -1 : dp[S];
        if (full != minCoinsLarge(coins, S)) { cout << "BŁĄD\n"; return 0; }
    }
    cout << "OK " << minCoinsLarge({1, 3, 4}, 1000000000000000000LL) << "\n";
