// Liczba ścieżek (prawo/dół) na planszy z przeszkodami '#', modulo 10^9+7.
#include <bits/stdc++.h>
using namespace std;
const long long MOD = 1'000'000'007;

int main() {
    int n, m;
    cin >> n >> m;
    vector<string> g(n);
    for (auto &row : g) cin >> row;
    vector<vector<long long>> dp(n, vector<long long>(m, 0));
    for (int i = 0; i < n; i++)
        for (int j = 0; j < m; j++) {
            if (g[i][j] == '#') { dp[i][j] = 0; continue; }
            if (i == 0 && j == 0) { dp[i][j] = 1; continue; }
            long long up = i > 0 ? dp[i - 1][j] : 0;
            long long left = j > 0 ? dp[i][j - 1] : 0;
            dp[i][j] = (up + left) % MOD;
        }
    cout << dp[n - 1][m - 1] << "\n";
}

// Ścieżka o maksymalnej sumie (prawo/dół) z odtworzeniem jako ciąg liter R/D.
#include <bits/stdc++.h>
using namespace std;

int main() {
    int n, m;
    cin >> n >> m;
    vector<vector<long long>> a(n, vector<long long>(m)), best(n, vector<long long>(m));
    for (auto &row : a) for (auto &x : row) cin >> x;
    for (int i = 0; i < n; i++)
        for (int j = 0; j < m; j++) {
            if (i == 0 && j == 0) best[i][j] = a[i][j];
            else if (i == 0) best[i][j] = best[i][j - 1] + a[i][j];
            else if (j == 0) best[i][j] = best[i - 1][j] + a[i][j];
            else best[i][j] = max(best[i - 1][j], best[i][j - 1]) + a[i][j];
        }
    cout << best[n - 1][m - 1] << "\n";
    string path;
    for (int i = n - 1, j = m - 1; i > 0 || j > 0; ) {      // cofamy się od mety
        if (i > 0 && (j == 0 || best[i - 1][j] >= best[i][j - 1])) { path += 'D'; i--; }
        else { path += 'R'; j--; }
    }
    reverse(path.begin(), path.end());
    cout << path << "\n";
}

