// LIS (ściśle rosnący) w O(n log n) z odtworzeniem jednego optymalnego podciągu.
#include <bits/stdc++.h>
using namespace std;

int main() {
    int n;
    cin >> n;
    vector<long long> a(n);
    for (auto &x : a) cin >> x;

    vector<long long> tails;     // tails[k] = najmniejszy koniec podciągu długości k+1
    vector<int> tailIdx;         // indeks w a elementu tails[k]
    vector<int> par(n, -1);      // poprzednik a[i] w podciągu kończącym się na a[i]
    for (int i = 0; i < n; i++) {
        int k = lower_bound(tails.begin(), tails.end(), a[i]) - tails.begin();  // upper_bound => niemalejący
        if (k == (int)tails.size()) { tails.push_back(a[i]); tailIdx.push_back(i); }
        else { tails[k] = a[i]; tailIdx[k] = i; }
        par[i] = (k > 0 ? tailIdx[k - 1] : -1);
    }

    int len = tails.size();
    vector<long long> seq;
    for (int i = tailIdx[len - 1]; i != -1; i = par[i]) seq.push_back(a[i]);
    reverse(seq.begin(), seq.end());
    cout << len << "\n";
    for (auto x : seq) cout << x << " ";
    cout << "\n";
}

// LIS w O(n^2) — prostsze, łatwo modyfikować (np. liczba LIS, warunek na parach).
#include <bits/stdc++.h>
using namespace std;

int main() {
    int n;
    cin >> n;
    vector<int> a(n);
    for (auto &x : a) cin >> x;
    vector<int> dp(n, 1), par(n, -1);
    for (int i = 0; i < n; i++)
        for (int j = 0; j < i; j++)
            if (a[j] < a[i] && dp[j] + 1 > dp[i]) { dp[i] = dp[j] + 1; par[i] = j; }
    int best = max_element(dp.begin(), dp.end()) - dp.begin();
    vector<int> seq;
    for (int i = best; i != -1; i = par[i]) seq.push_back(a[i]);
    reverse(seq.begin(), seq.end());
    cout << dp[best] << "\n";
    for (int x : seq) cout << x << " ";
    cout << "\n";
}

